<?php
/**
 * Offline Mode admin page.
 *
 * @package automattic/jetpack
 */

use Automattic\Jetpack\Admin_UI\Admin_Menu;
use Automattic\Jetpack\Status;
use Automattic\Jetpack\WP_Build_Polyfills\WP_Build_Polyfills;

/**
 * Registers the boot-backed Offline Mode screen.
 */
class Jetpack_Offline_Mode_Page {

	/**
	 * URL-facing wp-admin menu slug.
	 *
	 * @var string
	 */
	const MENU_SLUG = 'jetpack-offline-mode';

	/**
	 * Slug emitted by wp-build.
	 *
	 * @var string
	 */
	const WP_BUILD_SLUG = 'jetpack-offline-mode-page';

	/**
	 * Render function generated by wp-build.
	 *
	 * @var string
	 */
	const WP_BUILD_RENDER_FN = 'jetpack_offline_mode_jetpack_offline_mode_page_wp_admin_render_page';

	/**
	 * Position in the Jetpack submenu.
	 *
	 * @var int
	 */
	const MENU_POSITION = 1;

	/**
	 * Add hooks for the Offline Mode page.
	 *
	 * @return void
	 */
	public static function add_actions() {
		add_action( 'admin_init', array( __CLASS__, 'redirect_when_not_offline' ), 0 );
		add_action( 'admin_menu', array( __CLASS__, 'maybe_load_wp_build' ), 1 );
		add_action( 'jetpack_admin_menu', array( __CLASS__, 'add_menu_item' ) );
		self::fix_boot_import_map_ordering();
	}

	/**
	 * Redirect direct Offline Mode admin requests when the site is not in Offline Mode.
	 *
	 * @return void
	 */
	public static function redirect_when_not_offline() {
		if ( ! self::is_offline_mode_admin_request() || self::is_available() ) {
			return;
		}

		wp_safe_redirect( admin_url( 'admin.php?page=jetpack' ) );
		exit( 0 );
	}

	/**
	 * Load wp-build files for the Offline Mode admin request.
	 *
	 * @return void
	 */
	public static function maybe_load_wp_build() {
		if ( ! self::is_offline_mode_admin_request() || ! self::is_available() ) {
			return;
		}

		self::load_wp_build();

		add_action( 'current_screen', array( __CLASS__, 'alias_screen_id_for_wp_build' ) );
		add_action( 'admin_enqueue_scripts', array( __CLASS__, 'enqueue_initial_state' ), 11 );
		add_filter( 'admin_body_class', array( __CLASS__, 'add_body_class' ) );
	}

	/**
	 * Register the Offline Mode submenu under Jetpack.
	 *
	 * @return string|null The page hook suffix, if registered.
	 */
	public static function add_menu_item() {
		if ( ! self::is_available() ) {
			return null;
		}

		$callback = function_exists( self::WP_BUILD_RENDER_FN )
			? self::WP_BUILD_RENDER_FN
			: array( __CLASS__, 'render_fallback' );

		$page_suffix = Admin_Menu::add_menu(
			__( 'Offline Mode', 'jetpack' ),
			__( 'Offline Mode', 'jetpack' ),
			'manage_options',
			self::MENU_SLUG,
			$callback,
			self::MENU_POSITION
		);

		if ( $page_suffix ) {
			add_action( 'load-' . $page_suffix, array( __CLASS__, 'admin_init' ) );
		}

		return $page_suffix;
	}

	/**
	 * Whether the page should be available to the current user.
	 *
	 * @return bool
	 */
	public static function is_available() {
		return current_user_can( 'manage_options' ) && ( new Status() )->is_offline_mode();
	}

	/**
	 * Alias the screen id to the wp-build page slug so generated enqueues fire.
	 *
	 * @param WP_Screen|null $screen Current screen object.
	 * @return void
	 */
	public static function alias_screen_id_for_wp_build( $screen ) {
		if ( ! is_object( $screen ) ) {
			return;
		}

		$screen->id = self::WP_BUILD_SLUG;
	}

	/**
	 * Add page-specific body class for the Offline Mode layout stylesheet.
	 *
	 * @param string $classes Body classes.
	 * @return string
	 */
	public static function add_body_class( $classes ) {
		return $classes . ' jetpack-offline-mode-page';
	}

	/**
	 * Hide standard wp-admin notices on the focused Offline Mode page.
	 *
	 * @return void
	 */
	public static function admin_init() {
		remove_all_actions( 'admin_notices' );
		remove_all_actions( 'all_admin_notices' );
	}

	/**
	 * Fallback render used on unbuilt checkouts.
	 *
	 * @return void
	 */
	public static function render_fallback() {
		echo '<div class="wrap"><h1>' . esc_html__( 'Offline Mode', 'jetpack' ) . '</h1></div>';
	}

	/**
	 * Load wp-build registration files and polyfills.
	 *
	 * @return void
	 */
	private static function load_wp_build() {
		if ( class_exists( WP_Build_Polyfills::class ) ) {
			WP_Build_Polyfills::register(
				'jetpack-offline-mode',
				array_merge( WP_Build_Polyfills::SCRIPT_HANDLES, WP_Build_Polyfills::MODULE_IDS )
			);
		}

		$wp_build_index = JETPACK__PLUGIN_DIR . 'build/build.php';
		if ( file_exists( $wp_build_index ) ) {
			require_once $wp_build_index;
		}
	}

	/**
	 * Add initial state consumed by the wp-build stage.
	 *
	 * @return void
	 */
	public static function enqueue_initial_state() {
		if ( ! self::is_offline_mode_admin_request() || ! self::is_available() ) {
			return;
		}

		$initial_state = array(
			'apiNonce' => wp_create_nonce( 'wp_rest' ),
			'apiRoot'  => esc_url_raw( rest_url() ),
		);

		wp_add_inline_script(
			self::WP_BUILD_SLUG . '-wp-admin-prerequisites',
			'window.JetpackOfflineModeInitialState=' . wp_json_encode( $initial_state, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP ) . ';',
			'before'
		);
	}

	/**
	 * Fix import map ordering for the wp-build boot script.
	 *
	 * @return void
	 */
	public static function fix_boot_import_map_ordering() {
		$handle = self::WP_BUILD_SLUG . '-wp-admin-prerequisites';

		add_action(
			'admin_enqueue_scripts',
			static function () use ( $handle ) {
				if ( ! Jetpack_Offline_Mode_Page::is_offline_mode_admin_request() || ! Jetpack_Offline_Mode_Page::is_available() ) {
					return;
				}

				$data = wp_scripts()->get_data( $handle, 'after' );
				if ( empty( $data ) ) {
					return;
				}

				$boot_script = null;
				$remaining   = array();
				foreach ( $data as $line ) {
					if ( false !== strpos( $line, '@wordpress/boot' ) ) {
						$boot_script = $line;
					} else {
						$remaining[] = $line;
					}
				}

				if ( null === $boot_script ) {
					return;
				}

				wp_scripts()->add_data( $handle, 'after', $remaining );

				add_action(
					'admin_print_footer_scripts',
					static function () use ( $boot_script ) {
						wp_print_inline_script_tag( $boot_script, array( 'type' => 'module' ) );
					},
					20
				);
			},
			PHP_INT_MAX
		);
	}

	/**
	 * Whether the current request targets the Offline Mode admin page.
	 *
	 * @return bool
	 */
	public static function is_offline_mode_admin_request() {
		if ( ! is_admin() ) {
			return false;
		}

		// phpcs:ignore WordPress.Security.NonceVerification.Recommended
		if ( ! isset( $_GET['page'] ) ) {
			return false;
		}

		// phpcs:ignore WordPress.Security.NonceVerification.Recommended
		return self::MENU_SLUG === sanitize_text_field( wp_unslash( $_GET['page'] ) );
	}
}
